package com.pet.buscaativa;

import static org.junit.jupiter.api.Assertions.*;
import java.time.*;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.*;
import org.springframework.beans.factory.annotation.Autowired;
import com.pet.buscaativa.entities.*;
import com.pet.buscaativa.entities.enums.*;
import com.pet.buscaativa.repositories.*;

class CancellationAmbiguityCollisionTests extends CancellationRegularizationSupport {
    @Autowired GrupoTerapeuticoRepository groups;
    @Autowired SessaoGrupoRepository sessions;
    @Autowired SessaoGrupoParticipanteRepository participants;
    @ParameterizedTest @ValueSource(strings={"professional_active","patient_active","professional_historic","patient_historic","group_professional","group_patient"})
    void rf10To12ActualOrHistoricalConflictIsStructuredAndDoesNotExposeThirdParty(String kind) throws Exception {var a=canceled(false);tx(()->{if(kind.startsWith("group")){var g=new GrupoTerapeutico();g.setCoordenador(kind.equals("group_professional")?professional:colleague);g.setTema("Grupo sintético de conflito");groups.saveAndFlush(g);var s=new SessaoGrupo();s.setGrupo(g);s.setDataSessao(a.getDataAgendamento());s.setHorario(a.getHoraAtendimento());s.setStatus(StatusSessaoGrupo.AGENDADA);s.confirmarRealizacao(g.getCoordenador());sessions.saveAndFlush(s);var p=new SessaoGrupoParticipante();p.setSessaoGrupo(s);p.setPaciente(kind.equals("group_patient")?patient:other);p.setStatusPresenca(StatusPresencaGrupo.PRESENTE);participants.saveAndFlush(p);}else{boolean samePatient=kind.startsWith("patient");var neighbor=seed(samePatient?patient:other,samePatient?colleague:professional,kind.endsWith("active")?SituacaoAtendimento.AGENDADO:SituacaoAtendimento.PRESENTE,a.getDataAgendamento(),"08:00");if(kind.endsWith("historic")){neighbor.setSituacaoAtendimento(SituacaoAtendimento.CANCELADO);appointments.saveAndFlush(neighbor);}}return null;});var before=database();for(int i=0;i<2;i++){var r=factual(admin,a,fact(a,FrequenciaAssistencial.PRESENTE));assertEquals(409,r.getStatus());assertEquals("CONFLITO_ASSISTENCIAL_PENDENTE_RECONCILIACAO",json.readTree(r.getContentAsString()).get("codigo").asText());assertFalse(r.getContentAsString().contains(other.getNome()));assertEquals(before,database());}}
    @ParameterizedTest @ValueSource(strings={"missing_date","missing_time","ambiguous_time","migration","history_single","history_duplicate","fork","cycle","foreign_parent","root_flag"})
    void rf16Rf17AmbiguityNeverInventsFactsOrChoosesOneHistory(String defect) throws Exception {var a=canceled(false);long id=a.getId();tx(()->{var x=appointment(id);switch(defect){case "missing_date"->x.setDataAgendamento(null);case "missing_time"->x.setHoraAtendimento(null);case "ambiguous_time"->{x.setDataAgendamento(LocalDate.of(2012,2,25));x.setHoraAtendimento(LocalTime.of(23,30));}case "migration"->{jdbc.update("update tb_agendamento set migracao_pendente=true,motivo_migracao_pendente='Fixture sintética ambígua',frequencia_assistencial=null where id=?",id);return null;}case "history_single","history_duplicate"->{int n=defect.equals("history_single")?1:2;for(int i=0;i<n;i++){var h=new HistoricoPaciente();h.setPaciente(patient);h.setAgendamento(x);h.setProfissional(professional);h.setTipo(i==0?TipoEventoHistoricoPaciente.PRESENCA:TipoEventoHistoricoPaciente.FALTA);h.setSituacaoAtendimento(i==0?SituacaoAtendimento.PRESENTE:SituacaoAtendimento.FALTOU);h.setOcorridoEm(LocalDateTime.of(x.getDataAgendamento(),x.getHoraAtendimento()));history.saveAndFlush(h);}}case "root_flag"->x.setRemarcacaoAposFalta(true);default->{var parent=seed(defect.equals("foreign_parent")?other:patient,professional,SituacaoAtendimento.REMARCADO_ORIGEM,x.getDataAgendamento().minusDays(2),"08:00");x.setAgendamentoOriginal(parent);if(defect.equals("fork")){var sibling=seed(patient,colleague,SituacaoAtendimento.CANCELADO,x.getDataAgendamento().minusDays(1),"08:00");sibling.setAgendamentoOriginal(parent);appointments.saveAndFlush(sibling);}if(defect.equals("cycle")){parent.setAgendamentoOriginal(x);appointments.saveAndFlush(parent);}}}appointments.saveAndFlush(x);return null;});a=appointment(id);var before=database();var r=factual(admin,a,fact(a,FrequenciaAssistencial.PRESENTE));assertEquals(409,r.getStatus(),r.getContentAsString());assertEquals(before,database());}
    @Test void canceledKnownLegacyFactHasNoTrustedRegularizationOrigin() throws Exception {var a=tx(()->{var x=seed(patient,professional,SituacaoAtendimento.PRESENTE,DAY.minusDays(5),"08:00");x.setSituacaoAtendimento(SituacaoAtendimento.CANCELADO);return appointments.saveAndFlush(x);});var before=database();assertEquals(409,correct(admin,a,FrequenciaAssistencial.FALTOU));assertEquals(409,factual(a,FrequenciaAssistencial.FALTOU));assertEquals(before,database());}
    @Test void unexplainedVersionAfterRegularizationDoesNotCertifyProvenance() throws Exception {var a=canceled(false);assertEquals(200,factual(a,FrequenciaAssistencial.PRESENTE));long id=a.getId();tx(()->{var x=appointment(id);x.setTurnoAgendamento(TurnoEnum.TARDE);appointments.saveAndFlush(x);return null;});a=appointment(id);var before=database();assertEquals(409,correct(admin,a,FrequenciaAssistencial.FALTOU));assertEquals(before,database());}
    @Test void contradictoryClinicalHistoryAfterRegularizationRequiresReconciliation() throws Exception {var a=canceled(false);assertEquals(200,factual(a,FrequenciaAssistencial.PRESENTE));tx(()->{var h=history.findByAgendamento(a).stream().filter(x->x.getTipo()==TipoEventoHistoricoPaciente.PRESENCA).findFirst().orElseThrow();h.setSituacaoAtendimento(SituacaoAtendimento.FALTOU);history.saveAndFlush(h);return null;});var before=database();assertEquals(409,correct(admin,appointment(a.getId()),FrequenciaAssistencial.FALTOU));assertEquals(before,database());}
}
